    uint32_t sel_word = (sub < 8u) ? amdgpu::RegisterAccess(wf).read_scalar(src1)
                                   : amdgpu::RegisterAccess(wf).read_scalar(src2);
    uint32_t sel = (sel_word >> ((sub & 7u) * 4u)) & 0xF;
    uint32_t src_lane = (lane & ~0xFu) | sel;
